#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int tree[2004];
    int lowbit(int i) {
        return i & (-i);
    }

    int sum(int x) {
        int res = 0;
        for (int i = x; i > 0; i -= lowbit(i))
            res += tree[i];
        return res;
    }

    void add(int x, int v) {
        for (int i = x; i <= n; i += lowbit(i))
            tree[i] += v;
    }

    int n;
    int end_[27];    // 改名为 end_，避免关键字
    int pre[2004];
    int arr[2004];
    int tree1[2004];

    void add1(int x, int v) {
        for (int i = x; i <= n; i += lowbit(i))
            tree1[i] += v;
    }

    int sum1(int x) {
        int res = 0;
        for (int i = x; i > 0; i -= lowbit(i))
            res += tree1[i];
        return res;
    }

    void push(int i, int temp) {
        pre[temp] = end_[i];
        end_[i] = temp;
    }

    int pop1(int i) {
        int ans = end_[i];
        end_[i] = pre[end_[i]];
        return ans;
    }

    int minMovesToMakePalindrome(string s) {
        n = s.length();

        memset(tree, 0, sizeof(tree));
        memset(tree1, 0, sizeof(tree1));
        memset(pre, 0, sizeof(pre));
        memset(end_, -1, sizeof(end_)); // ✅ 必须 -1
        memset(arr, 0, sizeof(arr));

        for (int i = 1; i <= n; i++)
            add(i, 1);

        for (int i = 0, j = 1; i < s.size(); i++, j++)
            push(s[i] - 'a', j);

        for (int i = 0, l = 1, r; i < s.size(); i++, l++) {
            if (arr[l] == 0) {
                r = pop1(s[i] - 'a');
                if (l < r) {
                    int k = sum(l);
                    arr[l] = k;
                    arr[r] = n - k + 1;
                    add(r, -1); // ✅ 放这里才对！
                } else {
                    arr[l] = (n + 1) / 2;
                }
            }
        }

        int res = 0;
        for (int i = 1; i <= n; i++) {
            res += i - 1 - sum1(arr[i]);
            add1(arr[i], 1);
        }
        return res;
    }
};

// ==================== Obsidian 运行入口 ====================
int main() {
    Solution sol;
    string s;
    cout << "请输入字符串：";
    cin >> s;
    cout << "最小交换次数 = " << sol.minMovesToMakePalindrome(s) << endl;
    return 0;
}
